\title{Reflective Provability:\\ When ``Provable but Not Provably Provable'' Is Possible}
\author{Aristotle}
\date{2026-07-11}

\begin{document}
\maketitle

\begin{abstract}
We study a small propositional logic equipped with a modality $\Box$ read as \emph{provability}, in which a proposition may speak about its own provability. Within this language the self-referential sentence
\[ G(A) \;:=\; \Box A \wedge \neg\Box\Box A \qquad \text{(``$A$ is provable but not provably provable'')} \]
is a well-formed term. Using a Kripke (possible-worlds) semantics we establish a sharp dichotomy. First, $G(A)$ is \emph{satisfiable}: there is an explicit three-world, non-transitive model with a distinguished world at which $G(A)$ holds. Second, on every \emph{transitive} frame the axiom $4$ ($\Box A \to \Box\Box A$) is valid---the semantic content of $\Sigma_1$-completeness---and consequently $G(A)$ becomes \emph{unsatisfiable}. Provable-but-not-provably-provable is therefore possible precisely when provability fails to be provably transitive. We develop the semantics far enough to recover the normal modal logic $K$, the reflexive axiom $T$, and the diamond duality, and then, on the transitive converse-well-founded frames of Gödel--Löb logic $\mathsf{GL}$, we validate \textbf{Löb's theorem} $\Box(\Box A \to A) \to \Box A$ and derive \textbf{Gödel's second incompleteness theorem} $\Box(\neg\Box\bot) \to \Box\bot$ as the instance $A := \bot$.
\end{abstract}

\noindent\textbf{Keywords:} provability logic, modal logic, self-reference, Löb's theorem, Gödel's second incompleteness theorem, Kripke semantics, $\mathsf{GL}$, transitivity, converse well-foundedness.

\section{Introduction}

Self-reference is the engine of the foundational limitative theorems. Gödel's sentence asserts its own unprovability; the second incompleteness theorem concerns a theory's inability to prove its own consistency; Löb's theorem tames the fixed-point machinery into a single elegant schema. A unifying lens for all of these is \emph{provability logic}: propositional modal logic in which the modality $\Box$ is read as ``is provable.''

This paper isolates and analyzes the reflective sentence
\[ G(A) \;=\; \Box A \wedge \neg\Box\Box A, \]
``$A$ is provable but not provably provable.'' Our aims are threefold and elementary: (1)~\emph{expressibility}---$G(A)$ is a genuine well-typed term of a reflective language; (2)~\emph{contingency}---whether $G(A)$ can be true depends on the structure of provability, being satisfiable in a non-transitive frame and unsatisfiable in every transitive one; (3)~\emph{consequences}---the same semantics on transitive converse-well-founded frames yields Löb's theorem and Gödel's second incompleteness theorem. Everything is self-contained, using only elementary reasoning about relations together with well-founded induction.

\section{Syntax}

\subsection{Formulas}
Fix a countable set of atoms indexed by $\mathbb{N}$. The set of \textbf{formulas} is generated by
\[ A ::= p_n \mid \bot \mid (A \to A) \mid \Box A, \qquad n \in \mathbb{N}. \]
We define \textbf{negation} $\neg A := (A \to \bot)$, \textbf{conjunction} $A \wedge B := \neg(A \to \neg B)$, and the \textbf{diamond} $\Diamond A := \neg\Box\neg A$ (``$A$ is consistent'').

\begin{definition}[Gödelian reflection]
For a formula $A$ define $G(A) := \Box A \wedge \neg\Box\Box A$, the formal rendering of ``$A$ is provable but not provably provable.'' It is a well-formed term for every $A$.
\end{definition}

\section{Kripke semantics}

\begin{definition}[Model]
A \textbf{Kripke model} is a triple $M = (W, R, V)$ where $W$ is a set of \emph{worlds}, $R \subseteq W \times W$ is the \emph{accessibility relation}, and $V$ assigns to each atom $p_n$ and world $w$ a truth value.
\end{definition}

\begin{definition}[Satisfaction]
Satisfaction $M, w \bmodels A$ is defined by recursion on $A$:
\begin{itemize}
\item $M, w \bmodels p_n$ iff $V(n, w)$ holds;
\item $M, w \bmodels \bot$ never;
\item $M, w \bmodels A \to B$ iff ($M, w \bmodels A$ implies $M, w \bmodels B$);
\item $M, w \bmodels \Box A$ iff for all $v$ with $w \mathrel{R} v$, $M, v \bmodels A$.
\end{itemize}
A formula is \textbf{valid in $M$} ($M \bmodels A$) if it holds at every world, and \textbf{satisfiable} if it holds at some world of some model.
\end{definition}

\begin{lemma}[Negation]$M, w \bmodels \neg A$ iff $M, w \not\bmodels A$.\end{lemma}
\begin{lemma}[Conjunction]$M, w \bmodels A \wedge B$ iff $M, w \bmodels A$ and $M, w \bmodels B$.\end{lemma}
\begin{lemma}[Diamond]\label{lem:dia}$M, w \bmodels \Diamond A$ iff there exists $v$ with $w \mathrel{R} v$ and $M, v \bmodels A$.\end{lemma}
\begin{proof}
Unfolding, $\Diamond A = \neg\Box\neg A$, so $M, w \bmodels \Diamond A$ iff it is not the case that all $R$-successors $v$ satisfy $M, v \not\bmodels A$, which classically is the existence of an $R$-successor satisfying $A$.
\end{proof}

\section{The normal modal logic $K$}

\begin{theorem}[Distribution axiom $K$]
For all $A, B$, every $M$, $w$: $M, w \bmodels \Box(A \to B) \to (\Box A \to \Box B)$.
\end{theorem}
\begin{proof}
Assume $M, w \bmodels \Box(A \to B)$ and $M, w \bmodels \Box A$. Fix $v$ with $w \mathrel{R} v$; then $M, v \bmodels A \to B$ and $M, v \bmodels A$, hence $M, v \bmodels B$. As $v$ was arbitrary, $M, w \bmodels \Box B$.
\end{proof}

\begin{theorem}[Necessitation]
If $M \bmodels A$ then $M \bmodels \Box A$.
\end{theorem}
\begin{proof}
Fix $w$ and $v$ with $w \mathrel{R} v$; since $A$ is valid, $M, v \bmodels A$. Hence $M, w \bmodels \Box A$ for all $w$.
\end{proof}

\begin{theorem}[Reflexive axiom $T$]
If $R$ is reflexive then $M, w \bmodels \Box A \to A$ for all $A, w$.
\end{theorem}
\begin{proof}
Assume $M, w \bmodels \Box A$. By reflexivity $w \mathrel{R} w$, so $M, w \bmodels A$.
\end{proof}

\section{Satisfiability of the Gödelian reflection}

\begin{definition}[Witnessing model]
Let $W_0 = \{a, b, c\}$ with $R_0 = \{(a,b), (b,c)\}$ (the chain $a \to b \to c$) and valuation making every atom true at exactly the world $b$. Call this model $M_0$.
\end{definition}

\begin{theorem}[Satisfiability]\label{thm:sat}
$M_0, a \bmodels G(p_0)$; that is, $\Box p_0 \wedge \neg\Box\Box p_0$ holds at $a$.
\end{theorem}
\begin{proof}
\emph{($\Box p_0$ at $a$.)} The only $R_0$-successor of $a$ is $b$, and $p_0$ is true at $b$, so $M_0, a \bmodels \Box p_0$.

\emph{($\neg\Box\Box p_0$ at $a$.)} Suppose $M_0, a \bmodels \Box\Box p_0$. Since $a \mathrel{R_0} b$, this forces $M_0, b \bmodels \Box p_0$, hence $M_0, c \bmodels p_0$ because $b \mathrel{R_0} c$. But $p_0$ is false at $c$, a contradiction. So $M_0, a \bmodels \neg\Box\Box p_0$.
\end{proof}

\begin{theorem}[Non-transitivity of the witness]
The relation $R_0$ is not transitive.
\end{theorem}
\begin{proof}
$a \mathrel{R_0} b$ and $b \mathrel{R_0} c$, but $(a,c) \notin R_0$.
\end{proof}

\section{The transitivity dichotomy}

\begin{theorem}[Axiom $4$ on transitive frames]\label{thm:ax4}
If $R$ is transitive then $M, w \bmodels \Box A \to \Box\Box A$ for all $A, M, w$.
\end{theorem}
\begin{proof}
Assume $M, w \bmodels \Box A$. Fix $v$ with $w \mathrel{R} v$ and $u$ with $v \mathrel{R} u$. By transitivity $w \mathrel{R} u$, so $M, u \bmodels A$. As $u$, then $v$, are arbitrary, $M, w \bmodels \Box\Box A$.
\end{proof}

Axiom $4$ is the semantic form of \textbf{$\Sigma_1$-completeness}: whatever is provable is provably provable, since the existence of a proof is a verifiable finite fact.

\begin{theorem}[Unsatisfiability on transitive frames]\label{thm:unsat}
If $R$ is transitive then $M, w \not\bmodels G(A)$ for all $A, M, w$.
\end{theorem}
\begin{proof}
If $M, w \bmodels \Box A \wedge \neg\Box\Box A$, then $M, w \bmodels \Box A$ and, by Theorem~\ref{thm:ax4}, $M, w \bmodels \Box\Box A$, contradicting the second conjunct.
\end{proof}

\begin{corollary}[Dichotomy]
``Provable but not provably provable'' is realizable exactly when provability is not provably transitive: it can hold on non-transitive frames (Theorem~\ref{thm:sat}) and never on transitive frames (Theorem~\ref{thm:unsat}).
\end{corollary}

\section{Löb's theorem and Gödel's second incompleteness theorem}

The frames of \textbf{Gödel--Löb logic $\mathsf{GL}$} are the transitive, \emph{converse-well-founded} frames: there is no infinite sequence $w_0 \mathrel{R} w_1 \mathrel{R} w_2 \mathrel{R} \cdots$.

\begin{theorem}[Löb's theorem]\label{thm:loeb}
Let $R$ be transitive and converse-well-founded. Then $M, w \bmodels \Box(\Box A \to A) \to \Box A$ for all $A, w$.
\end{theorem}
\begin{proof}[Proof sketch]
Assume $M, w \bmodels \Box(\Box A \to A)$. Let $S$ be the set of $R$-successors of $w$ at which $A$ fails. If $S \neq \varnothing$, converse well-foundedness yields an $R$-maximal $v^\ast \in S$. For every $u$ with $v^\ast \mathrel{R} u$: transitivity gives $w \mathrel{R} u$ and maximality gives $u \notin S$, so $M, u \bmodels A$; thus $M, v^\ast \bmodels \Box A$. From $w \mathrel{R} v^\ast$ and the hypothesis, $M, v^\ast \bmodels \Box A \to A$, hence $M, v^\ast \bmodels A$---contradicting $v^\ast \in S$. So $S = \varnothing$ and $M, w \bmodels \Box A$.
\end{proof}

\begin{theorem}[Gödel's second incompleteness theorem]
On any transitive, converse-well-founded frame, $M, w \bmodels \Box(\neg\Box\bot) \to \Box\bot$.
\end{theorem}
\begin{proof}
Since $\neg\Box\bot = (\Box\bot \to \bot)$ is the Löb antecedent with $A := \bot$, Theorem~\ref{thm:loeb} with $A := \bot$ gives $M, w \bmodels \Box(\Box\bot \to \bot) \to \Box\bot$.
\end{proof}

\noindent\textbf{Interpretation.} Reading $\Box\bot$ as ``the system is inconsistent,'' $\neg\Box\bot$ is the consistency statement. The theorem says: if a system can prove its own consistency, then it is inconsistent. Contrapositively, a consistent system cannot prove its own consistency.

\section{Discussion}

\begin{center}
\begin{tabular}{lll}
\toprule
Frame condition & Governing logic & Status of $G(A)$ \\
\midrule
none & $K$ & satisfiable (Thm.~\ref{thm:sat}) \\
transitive & $K4$ & unsatisfiable (Thm.~\ref{thm:unsat}) \\
transitive + conv.\ well-founded & $\mathsf{GL}$ & unsatisfiable; Löb \& Gödel-2 hold \\
\bottomrule
\end{tabular}
\end{center}

The single sentence $G(A)$ acts as a probe: its satisfiability detects the absence of provable transitivity; its universal failure certifies $\Sigma_1$-completeness; and the well-founded refinement of the same models converts the picture into the classical incompleteness theorems. Notably, Gödel's second theorem---often presented through heavy arithmetization---appears as a one-line specialization of Löb's theorem.

\section{Applications}
\begin{itemize}
\item \textbf{Self-referential verification.} Systems certifying their own outputs implicitly manipulate a $\Box$ operator; once internal confidence becomes provable (axiom $4$), they inherit the Gödel boundary and cannot certify their own consistency from within.
\item \textbf{Confidence and meta-confidence.} The gap between $\Box A$ (confident) and $\Box\Box A$ (confident in one's confidence) is exactly $G(A)$; non-transitive confidence structures admit ``reliable but not reliably reliable'' states.
\item \textbf{Pedagogy.} The three-world witness gives a minimal object lesson separating one-step from two-step provability.
\end{itemize}

\section{Future directions}
\begin{enumerate}
\item \textbf{Hilbert-style proof system and completeness} for $K$, $K4$, $\mathsf{GL}$ (axioms $K$, $4$, Löb; MP and necessitation), with soundness and Kripke completeness for $\mathsf{GL}$ over finite transitive irreflexive frames, upgrading semantic unsatisfiability to syntactic underivability.
\item \textbf{Fixed points and arithmetical realization}: the de Jongh--Sambin fixed-point theorem, connecting $\Box$ to an actual provability predicate $\mathrm{Prov}_T$.
\item \textbf{Bimodal and polymodal reflection}: a second modality for ``true'' vs.\ ``provable'' (as in $\mathsf{Grz}$ or $\mathsf{GLS}$).
\item \textbf{Quantified / dependent version}: a dependent type theory whose universes carry a provability operator.
\item \textbf{Effectivity}: a decidable satisfaction check on finite models and a decision procedure for $\mathsf{GL}$.
\end{enumerate}

\section{Conclusion}
A single reflective sentence, ``provable but not provably provable,'' organizes a compact tour of provability logic: always expressible, satisfiable exactly on non-transitive frames, impossible exactly when provability is provably transitive, with Löb's theorem and Gödel's second incompleteness theorem emerging on the well-founded refinement. Self-reference becomes a precise instrument for locating the edge of what a formal system can know about its own knowing.

\end{document}

