"""Demo: explicit satisfiability of "provable but not provably provable"."""
from __future__ import annotations
from typing import Dict, List, Set, Tuple

Formula = tuple

def box(a: Formula) -> Formula: return ("box", a)
def imp(a: Formula, b: Formula) -> Formula: return ("imp", a, b)
def neg(a: Formula) -> Formula: return ("imp", a, ("bot",))
def conj(a: Formula, b: Formula) -> Formula: return neg(imp(a, neg(b)))
def atom(n: int) -> Formula: return ("atom", n)

def sat(rel: Set[Tuple[int, int]], val: Dict[Tuple[int, int], bool],
        phi: Formula, w: int, worlds: List[int]) -> bool:
    t = phi[0]
    if t == "atom": return val.get((phi[1], w), False)
    if t == "bot": return False
    if t == "imp": return (not sat(rel, val, phi[1], w, worlds)) or sat(rel, val, phi[2], w, worlds)
    if t == "box": return all(sat(rel, val, phi[1], v, worlds) for v in worlds if (w, v) in rel)
    raise ValueError(t)

def main() -> None:
    worlds = [0, 1, 2]                       # a, b, c
    rel = {(0, 1), (1, 2)}                   # a -> b -> c
    val = {(0, 1): True}                     # atom 0 true only at b
    A = atom(0)
    G = conj(box(A), neg(box(box(A))))
    print("Box A at a     :", sat(rel, val, box(A), 0, worlds))
    print("Box Box A at a :", sat(rel, val, box(box(A)), 0, worlds))
    print("G(A) at a      :", sat(rel, val, G, 0, worlds))

if __name__ == "__main__":
    main()

