"""Demo: Loeb's theorem and Goedel-2 hold on all small GL frames."""
from __future__ import annotations
from itertools import product
from typing import Dict, List, Set, Tuple

def box(a): return ("box", a)
def imp(a, b): return ("imp", a, b)
def neg(a): return ("imp", a, ("bot",))
def atom(n): return ("atom", n)
BOT = ("bot",)

def sat(rel, val, phi, w, worlds) -> bool:
    t = phi[0]
    if t == "atom": return val.get((phi[1], w), False)
    if t == "bot": return False
    if t == "imp": return (not sat(rel, val, phi[1], w, worlds)) or sat(rel, val, phi[2], w, worlds)
    if t == "box": return all(sat(rel, val, phi[1], v, worlds) for v in worlds if (w, v) in rel)

def transitive(rel) -> bool:
    return all((a, c) in rel for (a, b) in rel for (b2, c) in rel if b == b2)

def acyclic(rel, worlds) -> bool:
    color = {w: 0 for w in worlds}
    def dfs(u):
        color[u] = 1
        for v in worlds:
            if (u, v) in rel:
                if color[v] == 1 or (color[v] == 0 and dfs(v)): return True
        color[u] = 2; return False
    return not any(color[w] == 0 and dfs(w) for w in worlds)

def main() -> None:
    worlds = [0, 1, 2]
    pairs = [(i, j) for i in worlds for j in worlds]
    A = atom(0)
    loeb = imp(box(imp(box(A), A)), box(A))
    godel2 = imp(box(neg(box(BOT))), box(BOT))
    gl = 0
    for rbits in product([0, 1], repeat=len(pairs)):
        rel = {p for p, b in zip(pairs, rbits) if b}
        if not (transitive(rel) and acyclic(rel, worlds)): continue
        for vbits in product([0, 1], repeat=len(worlds)):
            val = {(0, w): bool(b) for w, b in zip(worlds, vbits)}
            assert all(sat(rel, val, loeb, w, worlds) for w in worlds)
            assert all(sat(rel, val, godel2, w, worlds) for w in worlds)
        gl += 1
    print("GL frames verified:", gl, "-- Loeb and Goedel-2 valid in all.")

if __name__ == "__main__":
    main()

