from __future__ import annotations
from typing import Dict, List, Set, Tuple

Formula = tuple  # ("atom", n) | ("bot",) | ("imp", A, B) | ("box", A)

def satisfies(worlds: List[int], relation: Set[Tuple[int, int]],
              valuation: Dict[Tuple[int, int], bool],
              phi: Formula, w: int) -> bool:
    """Recursive Kripke satisfaction: does phi hold at world w?"""
    tag = phi[0]
    if tag == "atom":
        return valuation.get((phi[1], w), False)
    if tag == "bot":
        return False
    if tag == "imp":
        left = satisfies(worlds, relation, valuation, phi[1], w)
        right = satisfies(worlds, relation, valuation, phi[2], w)
        return (not left) or right
    if tag == "box":
        return all(
            satisfies(worlds, relation, valuation, phi[1], v)
            for v in worlds if (w, v) in relation
        )
    raise ValueError(f"unknown tag {tag}")

