        return all(satisfies(worlds, relation, valuation, phi[1], v)
                   for v in worlds if (w, v) in relation)
    raise ValueError(tag)

def valid_on_frames(size: int, n_atoms: int, phi: Formula,
                    frame_filter) -> bool:
    """Return True iff phi is valid at every world of every frame of the
    given size (with n_atoms atoms) passing frame_filter(worlds, relation)."""
    worlds = list(range(size))
    pairs = [(i, j) for i in worlds for j in worlds]
    slots = [(a, w) for a in range(n_atoms) for w in worlds]
    for rbits in product([0, 1], repeat=len(pairs)):
        relation = {p for p, b in zip(pairs, rbits) if b}
        if not frame_filter(worlds, relation):
            continue
        for vbits in product([0, 1], repeat=len(slots)):
            valuation = {s: bool(b) for s, b in zip(slots, vbits)}
            if not all(satisfies(worlds, relation, valuation, phi, w)
                       for w in worlds):
                return False
    return True

