from __future__ import annotations
from typing import Dict, List, Set, Tuple

def is_transitive(worlds: List[int], relation: Set[Tuple[int, int]]) -> bool:
    return all((a, c) in relation
               for (a, b) in relation
               for (b2, c) in relation if b == b2)

def is_acyclic(worlds: List[int], relation: Set[Tuple[int, int]]) -> bool:
    """On a finite frame, converse-well-founded == acyclic (no forward cycle)."""
    color: Dict[int, int] = {w: 0 for w in worlds}
    def dfs(u: int) -> bool:
        color[u] = 1
        for v in worlds:
            if (u, v) in relation:
                if color[v] == 1:
                    return True
                if color[v] == 0 and dfs(v):
                    return True
        color[u] = 2
        return False
    return not any(color[w] == 0 and dfs(w) for w in worlds)

def is_gl_frame(worlds: List[int], relation: Set[Tuple[int, int]]) -> bool:
    """GL frame = transitive and converse-well-founded."""
    return is_transitive(worlds, relation) and is_acyclic(worlds, relation)

