"""Visualization: count of frames realizing G(A), transitive vs non-transitive."""
from itertools import product
import matplotlib.pyplot as plt

def box(a): return ("box", a)
def imp(a, b): return ("imp", a, b)
def neg(a): return ("imp", a, ("bot",))
def conj(a, b): return neg(imp(a, neg(b)))

def sat(rel, val, phi, w, worlds):
    t = phi[0]
    if t == "atom": return val.get((phi[1], w), False)
    if t == "bot": return False
    if t == "imp": return (not sat(rel, val, phi[1], w, worlds)) or sat(rel, val, phi[2], w, worlds)
    if t == "box": return all(sat(rel, val, phi[1], v, worlds) for v in worlds if (w, v) in rel)

def transitive(rel):
    return all((a, c) in rel for (a, b) in rel for (b2, c) in rel if b == b2)

def main() -> None:
    worlds = [0, 1, 2]
    pairs = [(i, j) for i in worlds for j in worlds]
    G = conj(box(("atom", 0)), neg(box(box(("atom", 0)))))
    t_yes = t_no = nt_yes = nt_no = 0
    for rbits in product([0, 1], repeat=len(pairs)):
        rel = {p for p, b in zip(pairs, rbits) if b}
        realizable = False
        for vbits in product([0, 1], repeat=len(worlds)):
            val = {(0, w): bool(b) for w, b in zip(worlds, vbits)}
            if any(sat(rel, val, G, w, worlds) for w in worlds):
                realizable = True; break
        if transitive(rel):
            if realizable: t_yes += 1
            else: t_no += 1
        else:
            if realizable: nt_yes += 1
            else: nt_no += 1
    fig, ax = plt.subplots(figsize=(7, 4))
    cats = ["transitive", "non-transitive"]
    yes = [t_yes, nt_yes]; no = [t_no, nt_no]
    ax.bar(cats, no, label="G(A) impossible", color="#8ecae6")
    ax.bar(cats, yes, bottom=no, label="G(A) realizable", color="#e07a5f")
    ax.set_ylabel("number of 3-world frames")
    ax.set_title("The transitivity dichotomy for 'provable but not provably provable'")
    ax.legend()
    plt.tight_layout(); plt.savefig("dichotomy.png", dpi=150)
    print(f"transitive: yes={t_yes} no={t_no}; non-transitive: yes={nt_yes} no={nt_no}")

if __name__ == "__main__":
    main()

